{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "flip",
  "supportive_card_ids": ["C55", "C56", "C61", "C63"],
  "contradictory_card_ids": ["C05", "C08", "C14", "C15", "C16", "C23", "C06", "C10", "C11", "C22", "C31", "C32", "C35", "C39", "C50", "C47", "C45", "C42", "C51", "C48"],
  "prediction_basis_card_ids": ["C55", "C56"],
  "claims": [
    {
      "claim": "Norfloxacin, the closest N-ethyl quinolone analog with human F data, has measured oral bioavailability of 30-40% (C05, C08, C15, C16) and fasting systemic availability of 22-60% with mean 40% (C14), but it is a mono-acid with a basic piperazine; the query is a dianionic bis-acid with no basic amine, so this transfer is limited.",
      "card_ids": ["C05", "C08", "C14", "C15", "C16", "C23"]
    },
    {
      "claim": "Ofloxacin and levofloxacin show absolute oral bioavailability approaching or virtually 100% (C10, C22), about 100% systemic availability in fasted subjects (C06), and 80-95% in cystic fibrosis patients (C11), but they also contain a basic amine and a single carboxyl, unlike the query.",
      "card_ids": ["C06", "C10", "C11", "C22"]
    },
    {
      "claim": "L3 nalidixic acid oral exposure records show measurable systemic exposure after oral dosing (AUC 17.25-17.34 µg·h/mL; Cmax 4.159-6.346 µg/mL) in a human crossover, supporting oral absorption of an N-ethyl quinolone acid, but no absolute F is reported and nalidixic acid has a single carboxyl.",
      "card_ids": ["C31", "C32", "C35", "C39"]
    },
    {
      "claim": "L4 fraction-absorbed records report near-complete or complete oral absorption for ofloxacin, levofloxacin, pefloxacin, enoxacin, and fleroxacin (C50, C47, C45, C42, C51, C48), but these analogs have a single carboxylic acid and a basic amine, so transfer to the dianionic bis-acid query is limited.",
      "card_ids": ["C50", "C47", "C45", "C42", "C51", "C48"]
    },
    {
      "claim": "L5 enalaprilat records provide measured low intestinal permeability for a dicarboxylic acid: effective permeability of 0.013 ± 0.009 ×10^-4 cm/s in rat jejunum (C56) and Papp of 4.61 ± 0.78 ×10^-6 cm/s in a nanoparticle dispersion (C55), supporting poor absorption of highly polar dicarboxylic acids.",
      "card_ids": ["C55", "C56"]
    },
    {
      "claim": "The query is fully ionized at pH 7.4 (neutral fraction 0), has two carboxylic acids, logD -3.24, and TPSA 126.8, consistent with the low-permeability dicarboxylic acid pattern shown by enalaprilat and unlike the well-absorbed zwitterionic quinolones.",
      "card_ids": ["C55", "C56"]
    },
    {
      "claim": "L5 efflux records for 7,8-DHF (C61, C63) show P-gp/MRP-mediated efflux of an anionic compound, providing additional but lower-transferability mechanistic evidence for possible presystemic loss; they are not direct F measurements.",
      "card_ids": ["C61", "C63"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "changed",
      "card_ids": ["C53", "C54", "C55", "C56", "C57", "C58", "C59", "C60", "C61", "C62", "C63", "C64"]
    }
  ],
  "evidence_gaps": [
    "No direct measured absolute oral bioavailability or permeability exists for the exact query molecule.",
    "No query-specific gut-wall efflux or intestinal metabolism data; enalaprilat and flavone records are from different chemotypes.",
    "Norfloxacin/ofloxacin/levofloxacin analogs have a basic amine and single carboxyl, limiting transfer to the dianionic bis-acid query.",
    "No first-pass hepatic metabolism or clearance data for the query.",
    "Food effects, formulation, and transporter-mediated absorption for the query are unverified."
  ],
  "decision_summary": "L5 adds mechanistic evidence that highly polar dicarboxylic acids can have very low intestinal permeability (enalaprilat P_eff 0.013e-4 cm/s, C56; Papp 4.61e-6 cm/s, C55). The query is a fully ionized bis-acid with logD -3.24 and no basic amine, unlike the well-absorbed mono-acid/basic-amine quinolones (norfloxacin, ofloxacin/levofloxacin). This new evidence, combined with the unfavorable physicochemical prior, supports F < 20%; prediction flipped to low with moderate confidence."
}

